insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('e56f0585-abef-423f-8aa9-24232d3672b6', '41e03373-9051-4add-a2fc-99b52681595a', $$inleiding: studenten moeten zich controleren op teken$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context1.png$$,
   $$Tijdens een introductieactiviteit van de hbo-opleiding Bos- en natuurbeheer spelen Stijn en zijn medestudenten een kennismakingsspel in het bos. Aan het eind van de dag wordt tegen alle studenten gezegd dat ze zich goed moeten controleren op teken.$$, 'inline'),
  ('f4dfee43-9ecb-45de-8243-ef5553078a85', '41e03373-9051-4add-a2fc-99b52681595a', $$teken en hun zuigsnuit (afbeelding 1 en 2)$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context2.png$$,
   $$Teken (Ixodes ricinus, afbeelding 1) wachten in het gras of in laag struikgewas op voorbijkomende dieren of mensen die hun een bloedmaaltijd kunnen verschaffen. Ze hechten zich met hun zuigsnuit (afbeelding 2) aan hun slachtoffer en voeden zich vervolgens met bloed uit de bloedvaten van de huid.
afbeelding 1: foto van een teek
afbeelding 2: elektronenmicroscopische opname van de kop van een teek met de zuigsnuit aangegeven (vergroting 100 x)$$, 'inline'),
  ('dab2de9d-0aa2-4a2e-9058-dcd141a0e54d', '41e03373-9051-4add-a2fc-99b52681595a', $$dikte van de opperhuid van een mens$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context3.png$$,
   $$De dikte van de opperhuid van een mens is tussen 30 en 2500 micrometer dik, afhankelijk van de plaats op het lichaam.$$, 'inline'),
  ('325f0279-a1a7-427f-93bd-c58b9fe384d2', '41e03373-9051-4add-a2fc-99b52681595a', $$speeksel van de teek: verdovende stof en stollingsremmer$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context4.png$$,
   $$’s Avonds bemerkt Stijn dat hij een teek in zijn knieholte heeft. Het speeksel van een teek bevat zowel een verdovende stof als een stof die bloedstolling tegengaat. Door de verdovende stof heeft Stijn de tekenbeet niet gevoeld en door de stollingsremmer kan de teek lange tijd bloed blijven zuigen zonder dat er stolsels ontstaan.$$, 'inline'),
  ('f68f113d-c2d2-419f-ac0c-c945d8719123', '41e03373-9051-4add-a2fc-99b52681595a', $$borrelia-bacterie veroorzaakt de ziekte van Lyme$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context5.png$$,
   $$Zo’n twintig procent van de teken in Nederland is geïnfecteerd met de borrelia-bacterie (Borrelia burgdorferi) en kan deze bacterie overbrengen op mensen. De bacterie is de veroorzaker van de ziekte van Lyme. Mensen met deze ziekte hebben vaak last van vermoeidheid en gewrichtsproblemen.$$, 'inline'),
  ('3e53cc4d-16d2-451a-948a-a1faf5831144', '41e03373-9051-4add-a2fc-99b52681595a', $$koorts: verschuiving van de norm; processen 1 t/m 3 die de lichaamstemperatuur beïnvloeden$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context6.png$$,
   $$Om de kans op besmetting met de borrelia-bacterie zo klein mogelijk te maken, verwijdert Stijn de teek direct met een tekentangetje. Mocht hij toch besmet zijn geraakt, dan zal zijn afweersysteem in actie komen om de bacterie onschadelijk proberen te maken. Als het niet lukt om de borrelia-bacterie onschadelijk te maken, kan de bacterie zich in het lichaam vermenigvuldigen. Dit leidt tot diverse lichamelijke klachten, waaronder koorts. Bij koorts wordt de norm voor de lichaamstemperatuur tijdelijk verschoven van 37 °C naar 38,5 °C of hoger. Vervolgens zullen diverse processen leiden tot een verhoging van de lichaamstemperatuur. Processen die de lichaamstemperatuur beïnvloeden zijn:
1 rillen en klappertanden
2 verhoging van de zweetproductie
3 vernauwing van bloedvaten in de huid$$, 'inline'),
  ('b604aefd-4585-4575-be36-89f25ef1c3ea', '41e03373-9051-4add-a2fc-99b52681595a', $$docent is immuun voor de borrelia-bacterie$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context7.png$$,
   $$Een docent van Stijn heeft de afgelopen jaren al tientallen tekenbeten gehad. Hij heeft onlangs zijn bloed laten onderzoeken. Hij blijkt nu niet besmet met de borrelia-bacterie, maar wel immuun te zijn voor deze bacterie.$$, 'inline'),
  ('26abbd2a-b259-451b-81e6-f71ebda14639', '41e03373-9051-4add-a2fc-99b52681595a', $$stoffen in het bloed wijzen op een eerdere infectie$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context8.png$$,
   $$Er worden stoffen in zijn bloed aangetoond die aangeven dat hij in het verleden een infectie met deze bacterie heeft gehad.$$, 'inline'),
  ('462adbf4-4073-47b4-8ce2-01c0da23e169', '41e03373-9051-4add-a2fc-99b52681595a', $$mutaties veranderen de eiwitten op het buitenoppervlak van de bacterie$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context9.png$$,
   $$De docent moet alert blijven op tekenbeten. Door mutaties veranderen de eiwitten op het buitenoppervlak van de borrelia-bacterie. Hierdoor is er een kans dat de docent bij een volgende infectie toch ziek kan worden.$$, 'inline'),
  ('fd9469de-2143-426f-9222-e46e8ebb2dea', '41e03373-9051-4add-a2fc-99b52681595a', $$antibiotica en resistente bacteriestammen$$,
   $$biologie-havo-2021-i-pas-op-voor-tekenbeten-context10.png$$,
   $$Als een arts de ziekte van Lyme vaststelt bij een patiënt schrijft de arts een antibioticum voor. Artsen zijn echter terughoudend in het voorschrijven van antibiotica. Door veelvuldig gebruik van antibiotica kunnen namelijk resistente bacteriestammen ontstaan. Je krijgt daarom niet bij iedere tekenbeet een antibioticum.$$, 'inline'),
  ('9a7727eb-6fcb-40fe-8c21-e6af853116e2', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$inleiding: Wouter onderzoekt het verbouwen van gewassen op marszand$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context1.png$$,
   $$Wouter onderzoekt voor zijn profielwerkstuk de mogelijkheid om voedselgewassen te verbouwen op Mars. Hij raakte geïnteresseerd nadat hij een nieuws-item zag waarin ecoloog Wieger Wamelink van Wageningen Universiteit vertelt met succes tomaten, bonen, worteltjes en aardappelen te hebben gekweekt op ‘marszand’. Nadat Wouter contact opnam met de onderzoeker, kreeg hij marszand om zelf enkele experimenten mee uit te voeren.$$, 'inline'),
  ('76a49ff3-02a6-4253-b553-7164b18a3121', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$samenstelling van marszand; afbeelding 1 (Marsrover Curiosity)$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context2.png$$,
   $$afbeelding 1: foto van de Marsrover Curiosity
Het marszand dat Wouter gebruikt, komt niet echt van Mars, maar is zand van vulkanische bodems op Hawaii. Dit zand vertoont grote gelijkenis met de bodem van Mars die de Marsrover Curiosity (afbeelding 1) analyseerde. Zand op Mars blijkt vooral fosfor, ijzeroxiden en stikstof te bevatten, maar ook enkele zware metalen.$$, 'inline'),
  ('337c8e0b-1598-4a38-9337-31caba4085a0', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$experiment bonenplanten op marszand en potgrond; beschikbare materialen$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context3.png$$,
   $$Met een experiment wil Wouter onderzoeken of bonenplanten geteeld op marszand evenveel biomassa produceren als bonenplanten geteeld op potgrond. Bij dit experiment heeft hij de beschikking over de volgende materialen:
− bonen (zaden)
− droogoven
− kweekbakken
− marszand
− potgrond
− water
− weegschaal$$, 'inline'),
  ('12e37fa3-1566-4fec-9899-82972b6733d0', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$abiotische factoren op Mars; tabel 1: samenstelling atmosfeer Mars en aarde$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context4.png$$,
   $$Naast de samenstelling van de bodem zijn er op Mars nog meer abiotische factoren die de plantengroei zullen beïnvloeden. De gemiddelde temperatuur op Mars is –55 °C. De luchtdruk op Mars is zeer laag, waardoor water heel snel zal verdampen via de huidmondjes. Ook de samenstelling van de atmosfeer is anders dan op aarde (tabel 1).
tabel 1 (Mars / aarde):
CO₂: 96,0% / 0,05%
N₂: 1,9% / 78,1%
O₂: 0,15% / 20,9%$$, 'inline'),
  ('50452dfb-9fab-4792-b5af-e27b9a819dba', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$drie uitspraken over processen in planten op Mars$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context5.png$$,
   $$Het verschil in abiotische factoren heeft gevolgen voor processen in de plant. Hierover worden drie uitspraken gedaan:
1 Door de samenstelling van de Mars-atmosfeer zullen de huidmondjes van planten op Mars langer open moeten zijn dan op aarde.
2 Zuurstof vormt op Mars een beperkende factor voor de fotosynthese.
3 De temperatuur vormt op Mars een beperkende factor voor de enzymactiviteit in planten.$$, 'inline'),
  ('4361cd63-67ab-4396-a2dc-a9766ab7fb5b', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$fosfor en stikstof in marszand; DNA en aminozuren$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context6.png$$,
   $$Marszand bevat fosfor (P) in de vorm van fosfaat, en het bevat stikstof (N) in de vorm van nitraat en ammonium. Een plant gebruikt fosfor en stikstof bij het maken van bepaalde organische stoffen. Twee voorbeelden van organische stoffen die voorkomen in een plant zijn DNA en aminozuren.$$, 'inline'),
  ('e363b93b-04d9-40cd-b7c8-89756388c887', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$bonenplanten in symbiose met stikstofbindende knolletjesbacteriën$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context7.png$$,
   $$Wouter denkt dat de teelt van bonen gebruikt kan worden om het nitraatgehalte in de bodem van Mars te verhogen. Bonenplanten leven in symbiose met stikstofbindende knolletjesbacteriën.$$, 'inline'),
  ('49940c48-7712-4e1a-9bc6-dbebb6ff5ea0', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$omzetting van stikstofhoudende organische stoffen; bodembacteriën 1 t/m 3$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context8.png$$,
   $$Als bonenplanten ondergespit worden, zetten bacteriën in de bodem de stikstofhoudende organische stoffen uit de plantenresten om tot nitraat. Bacteriën die voorkomen in de bodem op aarde zijn:
1 denitrificerende bacteriën
2 nitrificerende bacteriën
3 rottingsbacteriën
Bepaalde bacteriën zouden aan de bodem van Mars moeten worden toegevoegd om de omzetting van stikstofhoudende organische stoffen naar nitraat mogelijk te maken.$$, 'inline'),
  ('d02c26d5-d833-4cfb-b28d-b09eef100241', '060816b8-8b4e-49e2-a546-c96e40c7b87d', $$stikstofbinding door knolletjesbacteriën op Mars kleiner dan op aarde$$,
   $$biologie-havo-2021-i-groenten-telen-op-mars-context9.png$$,
   $$Als het lukt om op Mars in verwarmde kassen bonenplanten met de knolletjesbacteriën te telen zal de stikstofbinding door de knolletjesbacteriën minder groot zijn dan op aarde.$$, 'inline'),
  ('b0bfc418-8a99-4ffb-8c59-e381201ee13a', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$inleiding: scan van de buik (afbeelding 1) toont galstenen$$,
   $$biologie-havo-2021-i-galstenen-context1.png$$,
   $$Noor werkt als radiodiagnostisch laborant in een ziekenhuis. Ze maakt een scan van de buik van een patiënt. Deze patiënt kwam op de spoedeisende hulp met hevige pijn rechtsboven in de buik en met een gelige gelaatskleur. Op de scan (afbeelding 1) ziet Noor een witte plek op de lever. Dit bevestigt haar vermoeden dat het galstenen zijn die de buikpijn veroorzaken. Na overleg met de arts wordt de patiënt doorverwezen naar een internist voor behandeling.
afbeelding 1: scan van een dwarsdoorsnede van de buik met vier witte plekken P, Q, R en S (rechts en links aangegeven)$$, 'inline'),
  ('8f19ec23-10d9-4133-9286-db6318500631', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$op de scan zijn vier witte plekken met letters aangegeven$$,
   $$biologie-havo-2021-i-galstenen-context2.png$$,
   $$Op de scan zijn vier witte plekken met letters aangegeven.$$, 'inline'),
  ('c5e148b5-00bc-463f-a6a2-581acfacc993', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$bilirubine en ijzer uit de afbraak van hemoglobine$$,
   $$biologie-havo-2021-i-galstenen-context3.png$$,
   $$Galstenen kunnen ontstaan in de galblaas. Een deel van de galstenen bestaat voornamelijk uit bilirubine. Bilirubine is een afbraakproduct van hemoglobine en wordt met de gal uitgescheiden. Het ijzer (Fe³⁺) dat vrijkomt bij de afbraak van hemoglobine wordt – gebonden aan eiwitten in het bloedplasma – vervoerd naar weefsels waar nieuw hemoglobine wordt geproduceerd.$$, 'inline'),
  ('94bbe740-2269-41b5-9e1d-331c913aeb1b', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$in afbeelding 2 zijn organen met letters aangegeven$$,
   $$biologie-havo-2021-i-galstenen-context4.png$$,
   $$In afbeelding 2 is een aantal organen met letters aangegeven.$$, 'inline'),
  ('7cba5c53-5ce4-470b-b18a-51b98cba5e2e', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$afbeelding 2: vier organen P t/m S$$,
   $$biologie-havo-2021-i-galstenen-context5.png$$,
   $$afbeelding 2: vier tekeningen van het menselijk lichaam met telkens één orgaan donker gemarkeerd, aangegeven met P, Q, R en S$$, 'inline'),
  ('712b8885-4071-4da6-9017-90442589b0f9', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$afbeelding 3: galblaas met galstenen en buis X$$,
   $$biologie-havo-2021-i-galstenen-context6.png$$,
   $$In afbeelding 3 is de galblaas met enkele galstenen getekend. De galgang is geblokkeerd door een galsteen. Gal en stoffen die vervoerd worden via buis X hopen zich hierdoor op. Dit veroorzaakt de pijn bij de patiënt.
afbeelding 3: galblaas met galstenen, de galgang en de twaalfvingerige darm; buis X mondt samen met de galgang uit in de twaalfvingerige darm$$, 'inline'),
  ('74c868b1-1202-48ed-ad5e-ad97fc70ef12', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$bilirubine in het bloed; lijst van bloedvaten 1 t/m 10$$,
   $$biologie-havo-2021-i-galstenen-context7.png$$,
   $$Als de galgang geblokkeerd is, kan bilirubine niet worden uitgescheiden door de lever. Als gevolg hiervan komt de stof in een hoge concentratie in het bloed en in de huid terecht waardoor de patiënt een gele gelaatskleur krijgt. Een aantal bloedvaten zijn:
1 aorta
2 bovenste holle ader
3 haarvaten van de longen
4 haarvaten van het hart
5 leverader
6 leverslagader
7 longader
8 longslagader
9 onderste holle ader
10 poortader$$, 'inline'),
  ('ad8b1bf1-f424-4abf-98de-0536927f9a98', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$donkergekleurde urine door bilirubine$$,
   $$biologie-havo-2021-i-galstenen-context8.png$$,
   $$De urine van de patiënt was donkergekleurd. Dit duidt op de aanwezigheid van bilirubine.$$, 'inline'),
  ('8715b1c9-f442-43f2-88ef-02fb196e765b', '01aa7c63-c152-490c-9ffd-06ff4b12b27f', $$galblaas verwijderd; te weinig gal na een vette maaltijd$$,
   $$biologie-havo-2021-i-galstenen-context9.png$$,
   $$De internist besluit dat de galblaas van de patiënt moet worden verwijderd. Na de operatie krijgt de patiënt het advies om vette maaltijden te vermijden. Zonder galblaas wordt er namelijk te weinig gal afgegeven na een vette maaltijd.$$, 'inline'),
  ('b8248879-9bce-4f84-a7a9-89d4140e59b7', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$inleiding: chrysanten in verschillende kleuren en vormen$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context1.png$$,
   $$De van oorsprong gele chrysant wordt in Nederland volop gekweekt. Er zijn witte (afbeelding 1), roze, rode en paarse variëteiten. Sommige hebben grote bloemen, andere juist kleine.$$, 'inline'),
  ('f3b3b6a0-5f6b-4726-976d-95f49be33adc', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$afbeelding 1: witte chrysanten$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context2.png$$,
   $$afbeelding 1: foto van witte chrysanten$$, 'inline'),
  ('ec16ad5b-b444-4686-8e4c-854b53662d7e', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$klassieke veredeling: selectie en isolatie$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context3.png$$,
   $$De verschillende chrysanten-rassen zijn ontwikkeld door klassieke veredeling: dit is veredeling door middel van kruisingen waarbij wordt geselecteerd op gewenste kleuren en vormen. Bij klassieke veredeling spelen − net als bij evolutie − selectie en isolatie een rol.$$, 'inline'),
  ('c5ab1977-f663-4c7f-b000-d404b0b4dc0c', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$veredeling versnellen met radioactieve straling en weefselkweek$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context4.png$$,
   $$Het kost jaren voordat gewenste eigenschappen uiteindelijk via klassiek veredelen in de planten vóórkomen en er sprake is van een nieuw ras. Bij het veredelen van chrysanten wordt gebruikgemaakt van de genetische variatie van de planten. Om het veredelingsproces te versnellen, bestralen veredelaars plantendelen met radioactieve straling. Cellen van bladeren en stengels worden vervolgens op voedingsbodems opgekweekt tot volledige planten.$$, 'inline'),
  ('1ade772f-769d-4a3b-9096-527b503c7d21', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$radioactieve straling leidt tot extra variatie in het erfelijk materiaal$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context5.png$$,
   $$De radioactieve straling leidt tot extra variatie in het erfelijk materiaal.$$, 'inline'),
  ('403bc022-964b-4c65-8c22-460541e26e33', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$plantenhormonen bij weefselkweek$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context6.png$$,
   $$Bij weefselkweek worden hormonen toegevoegd waardoor de cellen andere organen vormen, zoals wortels.$$, 'inline'),
  ('d52036ba-aa66-4140-b6c6-c2982b072d03', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$eisen voor registratie als nieuw ras; kwekersrecht voor de chrysant Tokio$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context7.png$$,
   $$Om als nieuw ras te worden geregistreerd moet een variëteit aan drie eisen voldoen:
− Zij moet zich onderscheiden van andere rassen.
− Alle planten moeten op elkaar lijken.
− De kenmerkende eigenschappen blijven na vermeerderen behouden. Als hieraan is voldaan krijgt de veredelaar kwekersrecht. Hiermee kan hij gedurende 25 jaar beslissen wie het ras mag telen.
Kwekerij Flowi heeft ter gelegenheid van de Olympische Spelen de helderrode chrysant ‘Tokio’ gekweekt en hiervoor het kwekersrecht gekregen. Chrysanten van het ras Tokio worden ongeslachtelijk vermeerderd.$$, 'inline'),
  ('7ffd7bbf-63b2-4ad2-ab3e-22a5fb471523', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$drie uitspraken over het ras Tokio$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context8.png$$,
   $$Over het ras Tokio worden drie uitspraken gedaan:
1 Tokio moet voor alle kenmerkende eigenschappen homozygoot zijn.
2 Tokio heeft alleen maar dominant overervende eigenschappen.
3 Tokio kan niet worden gekruist met planten van een ander chrysantenras.$$, 'inline'),
  ('a45100f0-bf6a-4319-a231-2c7d938555ea', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$Tokio en Red Sun; afbeelding 2: DNA-fingerprints$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context9.png$$,
   $$Na enige tijd verschenen vrijwel identieke chrysanten onder de naam ‘Red Sun’ op de markt. Om te onderzoeken of dit echt een ander ras is dan de Tokio klopte Flowi aan bij Naktuinbouw (Stichting Nederlandse Algemene Kwaliteitsdienst Tuinbouw). Deze dienst kan onderzoeken of een kweker planten teelt waarop een andere kweker het kwekersrecht heeft.
Om na te gaan of Tokio en Red Sun tot hetzelfde ras behoren, worden ze in kassen opgekweekt en vervolgens vergeleken op de kenmerkende eigenschappen. Daarnaast worden genetische verschillen in kaart gebracht door middel van DNA-onderzoek. Hiermee wordt van elk ras een unieke DNA-fingerprint verkregen. In afbeelding 2 zijn de fingerprints van verschillende rassen weergegeven.
afbeelding 2: DNA-fingerprints (bandenpatronen) in de laantjes L en 1 t/m 14, met merkers bij 458 bp en 267 bp$$, 'inline'),
  ('ff307cdc-af16-4aca-9690-2c2f0af66e76', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$referentierassen voor de DNA-fingerprint$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context10.png$$,
   $$Van een tiental andere chrysantenrassen is ook een DNA-fingerprint gemaakt. Deze rassen worden gebruikt als referentierassen. Dat is nodig om te bepalen in welke mate chrysantenrassen normaal gezien van elkaar verschillen.$$, 'inline'),
  ('1e85096b-a1f2-4332-9c1f-c217ce9beb21', '348e045c-0a11-4d19-bbde-fa1b692992c6', $$resultaat van het onderzoek van Naktuinbouw met invulplaatsen (1) en (2)$$,
   $$biologie-havo-2021-i-verdachte-chrysanten-context11.png$$,
   $$Uit het onderzoek van Naktuinbouw bleek dat het kwekersrecht van Flowi was geschonden: De verschillen tussen de referentierassen bleken …(1)... de verschillen tussen Tokio en Red Sun. Dit resultaat bevestigt dat Tokio en Red Sun tot …(2)… behoren.$$, 'inline'),
  ('66f3df60-48b3-4607-a2aa-1587aa25cc0b', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$inleiding: gifstoffen van zeeslakken als medicijn tegen pijn$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context1.png$$,
   $$Voor de speurtocht naar nieuwe geneesmiddelen zijn zeeslakken zeer interessant. De gifstoffen die sommige zeeslakken maken, worden al gebruikt als medicijn bij de behandeling van chronische pijn.$$, 'inline'),
  ('a0e1f735-f86e-4eb2-87dc-4e1f6ab5a1aa', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$Conus-slakken produceren kleine giftige eiwitten; afbeelding 1$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context2.png$$,
   $$De slakken van het geslacht Conus (afbeelding 1) produceren kleine giftige eiwitten die ze met een harpoenachtig orgaan bij hun prooi injecteren. De variatie in gifstoffen binnen de 600 soorten van dit geslacht is zeer groot. Al deze gifstoffen werken als zenuwgif, waardoor ze mogelijk geschikt zijn als medicijn bij zenuwaandoeningen.
afbeelding 1: foto van een Conus-slak$$, 'inline'),
  ('42ede572-36ae-4757-95b8-3d13b229cced', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$de kleinste gifstof bestaat uit 17 aminozuren, gemaakt op basis van RNA$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context3.png$$,
   $$Een opvallend kenmerk van de giftige eiwitten is de grootte. De meeste gifstoffen van slangen en andere dieren zijn meer dan 50 aminozuren lang, maar gifstoffen van zeeslakken zijn kleiner. De kleinste bestaat uit slechts 17 aminozuren. Deze eiwitten worden gemaakt op basis van de code in een RNA-keten.$$, 'inline'),
  ('d91756f1-5daa-4af0-901e-a20fc10a5980', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$aminozuurvolgordes van gifstoffen vergeleken voor een stamboom$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context4.png$$,
   $$Voor het maken van een evolutionaire stamboom van de Conus-slakken werden de aminozuurvolgordes van hun gifstoffen met elkaar vergeleken. Het gif van de slak Conus consors is vergeleken met dat van drie andere slakken (tabel 1).$$, 'inline'),
  ('6a687a6d-92dd-43a2-910d-e3285eecfba2', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$tabel 1: overeenkomst in aminozuurvolgorde met gif van Conus consors$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context5.png$$,
   $$tabel 1: overeenkomst in aminozuurvolgorde met gif van Conus consors
Conus consors: 100%
Conus striatus: 86%
Conus stercusmuscarum: 80%
Conus kinoshitai: 75%$$, 'inline'),
  ('42d1ecf1-24cb-4330-87aa-84d94da42b17', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$de opgestelde stamboom staat in afbeelding 2$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context6.png$$,
   $$De stamboom die is opgesteld met deze gegevens is weergegeven in afbeelding 2.$$, 'inline'),
  ('53b90087-58e1-4f6a-8a9f-9e4d86dc89fe', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$afbeelding 2: stamboom met Conus consors en de nummers 1, 2 en 3$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context7.png$$,
   $$afbeelding 2: stamboom met vier eindpunten, van boven naar beneden: 1, Conus consors, 2 en 3; 1 en Conus consors splitsen het laatst af, 3 het eerst$$, 'inline'),
  ('3246a8ac-cf41-43e1-8e4e-86eb61ff5189', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$in de stamboom zijn de andere drie slakken met nummers aangegeven$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context8.png$$,
   $$In de stamboom is Conus consors al aangegeven. De andere drie slakken zijn met nummers aangegeven.$$, 'inline'),
  ('6001d9fd-ef9b-43aa-abff-c1d1f5a2db9e', 'c7e8798b-8341-49e6-8e12-ff53b8017ef5', $$gif blokkeert Ca²⁺-kanalen; vier stappen in het doorgeven van een pijnprikkel$$,
   $$biologie-havo-2021-i-zeeslak-maakt-pijnstiller-context9.png$$,
   $$De gifstof die door Conus magus wordt geproduceerd, wordt nu al gebruikt als pijnstiller. Het gif blokkeert de Ca²⁺-kanalen in de uiteinden van axonen. Hierdoor wordt de impulsoverdracht in de synapsen verstoord. Vier stappen in het doorgeven van een pijnprikkel van een perifere zenuwcel naar een cel in de sensorische hersenschors zijn:
1 Blaasjes met neurotransmitters fuseren met het synapsmembraan.
2 De drempelwaarde van een sensorische zenuwcel wordt overschreden.
3 Impulsen worden geleid over een sensorische zenuwuitloper.
4 Neurotransmitters binden aan receptoren van een schakelzenuwcel.$$, 'inline'),
  ('ebb11cd7-5c06-4792-9b94-791e28ef689d', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$inleiding: bacteriën veranderen planten in zombies$$,
   $$biologie-havo-2021-i-zombieplanten-context1.png$$,
   $$‘Plants versus zombies’ is een videospelletje waarin planten vechten tegen zombies. In werkelijkheid zijn sommige planten zelf zombies. Wetenschappers hebben ontdekt hoe bepaalde bacteriën sommige planten tot levende doden transformeren.$$, 'inline'),
  ('9784bd8c-5117-4dd0-9093-0b88e2ac3066', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$fytoplasma's leven in transportweefsel en verhinderen bloemvorming$$,
   $$biologie-havo-2021-i-zombieplanten-context2.png$$,
   $$Deze bacteriën − fytoplasma’s genaamd − kunnen een verscheidenheid aan gewassen besmetten, zoals tomatenplanten en appelbomen. Fytoplasma’s leven en vermenigvuldigen zich in transportweefsel van deze planten. De bacteriën verhinderen de ontwikkeling van bloemen en stimuleren de vorming van extra bladeren. De geïnfecteerde plant kan zich hierdoor niet meer voortplanten en dient als groeiende voedselbron voor de bacteriën, vandaar de term zombieplanten.$$, 'inline'),
  ('4db2824d-9246-4bb7-a609-67561a0910b9', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$verspreiding van fytoplasma's door dwergcicaden$$,
   $$biologie-havo-2021-i-zombieplanten-context3.png$$,
   $$Fytoplasma’s zijn voor hun verspreiding afhankelijk van bepaalde insecten zoals dwergcicaden. Dwergcicaden voeden zich met plantensap. Met hun zuigsnuit prikken ze in een blad waarna ze, minutenlang, energierijk plantensap opzuigen. Wanneer ze een met fytoplasma geïnfecteerde plant aanprikken, zuigen ze ook de bacterie op. Als de dwergcicade hierna een andere plant bezoekt, kan de bacterie via het speeksel van de dwergcicade deze plant ook besmetten.$$, 'inline'),
  ('24eee483-d20c-4f42-aa3b-282d334fa63d', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$in afbeelding 1 is een schematische doorsnede van een besmet blad weergegeven$$,
   $$biologie-havo-2021-i-zombieplanten-context4.png$$,
   $$In afbeelding 1 is een schematische doorsnede van een met fytoplasma’s besmet blad weergegeven.$$, 'inline'),
  ('a602fc77-9f0e-4fcf-954d-1830ac72a630', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$afbeelding 1: doorsnede van een blad$$,
   $$biologie-havo-2021-i-zombieplanten-context5.png$$,
   $$afbeelding 1: schematische doorsnede van een blad met epidermis, palissadeparenchym, intercellulaire ruimte, houtvaten, bastvaten en een huidmondje$$, 'inline'),
  ('ed40d3f6-2da2-46a8-b8eb-0e4eb543e50d', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$de relatie tussen fytoplasma en dwergcicade is een vorm van symbiose$$,
   $$biologie-havo-2021-i-zombieplanten-context6.png$$,
   $$De relatie tussen fytoplasma en dwergcicade is een vorm van symbiose.$$, 'inline'),
  ('5968cd41-057c-402e-8190-dd39733063db', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$experiment: voorkeur van dwergcicaden voor geïnfecteerde planten$$,
   $$biologie-havo-2021-i-zombieplanten-context7.png$$,
   $$Doordat slechts een klein deel van de planten van een soort geïnfecteerd is, zou het gunstig zijn voor de verspreiding van fytoplasma’s als dwergcicaden een voorkeur hebben voor geïnfecteerde planten. In een experiment wordt uitgezocht of de dwergcicaden inderdaad een voorkeur hebben voor geïnfecteerde planten. De onderzoekers richten een kas in met geïnfecteerde en niet-geïnfecteerde tomatenplanten en laten hierin dwergcicaden los.$$, 'inline'),
  ('3fa99cdd-72de-4e59-b0ca-2642fa7e5e5c', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$eiwit SAP54 zorgt voor afbraak van MTF-eiwitten die bloei-genen activeren$$,
   $$biologie-havo-2021-i-zombieplanten-context8.png$$,
   $$Onderzoekers van de Wageningen Universiteit hebben ontdekt hoe de fytoplasma’s de ontwikkeling van de planten manipuleren. De bacterie produceert een eiwit (SAP54) waardoor bepaalde planteneiwitten (MTF- eiwitten) afgebroken worden. Normaal activeren deze MTF-eiwitten de bloei-genen die nodig zijn voor het vormen van bloemen aan de plant.$$, 'inline'),
  ('be232de3-54a9-4cfe-951a-5810308f96c9', '3cc45cbe-2403-4870-89c1-b0ba56ee0d15', $$moleculaire veranderingen: eiwitten, RNA en aantal bloei-genen$$,
   $$biologie-havo-2021-i-zombieplanten-context9.png$$,
   $$Door de infectie zijn op moleculair niveau veranderingen in de plant waarneembaar. Weefsel waar normaal de bloemvorming start, is onderzocht bij geïnfecteerde en bij gezonde planten. Bepaald is:
1 de hoeveelheid door bloei-genen gecodeerde eiwitten
2 de hoeveelheid RNA van de bloei-genen
3 het aantal verschillende bloei-genen$$, 'inline'),
  ('1da9019e-f200-4874-b414-d28ff57465a2', '4ded5806-0d3b-4e3a-98e6-c28e5fc6bfa9', $$inleiding: Maranja heeft het 18p-tetrasomiesyndroom$$,
   $$biologie-havo-2021-i-18p-tetrasomie-context1.png$$,
   $$Maranja is een meisje van bijna twee jaar oud met het 18p-tetrasomiesyndroom. Door haar ontwikkelingsachterstand heeft Maranja veel zorg nodig.$$, 'inline'),
  ('080f44b1-d7d0-4b2a-9c24-f4513fe14640', '4ded5806-0d3b-4e3a-98e6-c28e5fc6bfa9', $$18p-tetrasomie: extra chromosoom i18p; afbeelding 1: chromosoom 18 en i(18p)$$,
   $$biologie-havo-2021-i-18p-tetrasomie-context2.png$$,
   $$18p-tetrasomie is een zeldzame afwijking waarbij elke lichaamscel naast de normale set chromosomen een extra chromosoom bevat. Dit extra chromosoom (i18p) bestaat uit twee keer de korte arm van chromosoom 18 (afbeelding 1).
afbeelding 1: chromosoom 18 met korte arm (p-arm), centromeer en lange arm (q-arm), en het extra chromosoom i(18p) dat bestaat uit twee korte armen (p-armen)
Een aantal genen komt hierdoor vier keer voor in elke cel. Dit verstoort de aanleg van organen tijdens de ontwikkeling van het kind in de baarmoeder.$$, 'inline'),
  ('7dba71e2-fbc1-4140-8c4a-8b45367dd50f', '4ded5806-0d3b-4e3a-98e6-c28e5fc6bfa9', $$het karyotype beschrijft aantal chromosomen, geslachtschromosomen en extra chromosomen$$,
   $$biologie-havo-2021-i-18p-tetrasomie-context3.png$$,
   $$De diagnose 18p-tetrasomiesyndroom werd bij Maranja bevestigd door haar karyotype te bepalen uit een karyogram. Het karyotype beschrijft per lichaamscel het totale aantal chromosomen, de geslachtschromosomen, en eventuele extra chromosomen.$$, 'inline'),
  ('6f6cf4e1-6ff4-45c5-af76-43fc36553b21', '4ded5806-0d3b-4e3a-98e6-c28e5fc6bfa9', $$opening tussen de twee hartkamers$$,
   $$biologie-havo-2021-i-18p-tetrasomie-context4.png$$,
   $$Maranja heeft, net als veel andere mensen met 18p-tetrasomie, een opening tussen de twee hartkamers. Hierdoor stroomt bloed van de ene hartkamer naar de andere.$$, 'inline'),
  ('d170b912-a80a-4af0-8612-06746c65922a', '4ded5806-0d3b-4e3a-98e6-c28e5fc6bfa9', $$voeding via een maagsonde (afbeelding 2)$$,
   $$biologie-havo-2021-i-18p-tetrasomie-context5.png$$,
   $$Maranja kan geen vaste voeding eten omdat ze niet kan slikken. Via een maagsonde wordt haar voeding direct in de maag gebracht (afbeelding 2). Maranja’s moeder pureert groenten, fruit en vlees. Door de juiste hoeveelheid water toe te voegen is het geschikt als sondevoeding.
afbeelding 2: tekening van een maagsonde met maag, aansluiting door de buikwand, sonde en spuit met voedingsmengsel$$, 'inline'),
  ('62b6c9e6-ef38-408f-8cde-6bb9e35e6b20', '4ded5806-0d3b-4e3a-98e6-c28e5fc6bfa9', $$vertering van zetmeel uit de sondevoeding begint pas in de twaalfvingerige darm$$,
   $$biologie-havo-2021-i-18p-tetrasomie-context6.png$$,
   $$De vertering van zetmeel uit de sondevoeding begint bij Maranja pas in de twaalfvingerige darm. Zelfs al zou speeksel van Maranja in haar maag komen, dan zouden de speekselenzymen daar zetmeel niet of nauwelijks kunnen verteren.$$, 'inline'),
  ('5849054a-33ab-42aa-880c-6bb3335b05ac', '797dc471-175d-4a84-9137-7ef522c19414', $$inleiding: massale sterfte van vleermuizen in Noord-Amerika door een schimmel$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context1.png$$,
   $$In Noord-Amerika werden in 2006 opeens veel dode vleermuizen gevonden. Ze bleken besmet met een schimmel. Onderzoekers doen onderzoek om het uitsterven van vleermuissoorten te voorkomen.$$, 'inline'),
  ('34d40a2a-ff03-42b1-b777-a686d588fe3b', '797dc471-175d-4a84-9137-7ef522c19414', $$witteneuzensyndroom en winterslaap; afbeelding 1 (vleermuis) en afbeelding 2 (voedselweb)$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context2.png$$,
   $$De schimmel Pseudogymnoascus destructans tast het huidweefsel van de snuit, oren en vleugels van vleermuizen aan. Doordat de neus wit kleurt (afbeelding 1) wordt de ziekte witteneuzensyndroom (WNS) genoemd. Vleermuizen zijn voor hun voedsel afhankelijk van vliegende insecten. ’s Winters overbruggen vleermuizen deze voedselloze periode door in winterslaap te gaan: ze verlagen hun stofwisselingsniveau waardoor hun lichaamstemperatuur daalt. Gedurende de winterslaap worden ze enkele keren actief, waarbij hun lichaamstemperatuur kortdurend stijgt. Wanneer de lichaamstemperatuur van de vleermuizen laag is, slaat P. destructans toe.
afbeelding 1: foto van een vleermuis met een witte neus
In afbeelding 2 zie je een vereenvoudigd voedselweb waarvan vleermuizen in Noord-Amerika deel uitmaken.
afbeelding 2: voedselweb met uilen, roofvogels, marters, slangen, muizen, kleine vogels, vleermuizen, kevers, motten, vliegende mieren, eendagsvliegen en muggen$$, 'inline'),
  ('d323737f-5b4c-47ad-8722-440c5bb70733', '797dc471-175d-4a84-9137-7ef522c19414', $$reducenten ontbreken in het voedselweb$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context3.png$$,
   $$Zoals gebruikelijk ontbreken in dit voedselweb de reducenten zoals P. destructans.$$, 'inline'),
  ('4a3ba2f3-a82f-49a1-85a0-dee0a98b218c', '797dc471-175d-4a84-9137-7ef522c19414', $$vaker ontwaken tijdens de winterslaap: vetreserve raakt eerder op$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context4.png$$,
   $$Als de vleermuizen vaak ontwaken tijdens hun winterslaap, raakt hun vetreserve eerder op. Dit zou de waargenomen sterfte kunnen verklaren.$$, 'inline'),
  ('5eaf6fe4-a329-4113-86e5-c7bf7bceaa4e', '797dc471-175d-4a84-9137-7ef522c19414', $$NAPd en EUPd; tabel 1 en indeling van de vleermuizen in drie groepen$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context5.png$$,
   $$Canadese onderzoekers vermoedden dat vleermuizen vaker ontwaken als gevolg van een infectie met P. destructans. Hiermee zou deze schimmel ook verantwoordelijk zijn voor de massale sterfte. In Europa komt ook een variant van deze schimmel voor: EUPd. Massale sterfte van Europese vleermuizen blijft echter uit (tabel 1). Uit veldwaarnemingen blijkt dat EUPd niet voorkomt in Noord-Amerika.
tabel 1 (massale sterfte / variant van P. destructans):
Noord-Amerika: ja / NAPd
Europa: nee / EUPd
Om te onderzoeken waardoor Noord-Amerikaanse vleermuizen massaal sterven, vingen de onderzoekers niet-geïnfecteerde Noord-Amerikaanse vleermuizen uit een grot in Canada en verdeelden ze in drie groepen van elk 18 vleermuizen.
− Groep 1 werd geïnjecteerd met NAPd in fysiologische zoutoplossing.
− Groep 2 werd geïnjecteerd met EUPd in fysiologische zoutoplossing.
− Groep 3 was de controlegroep.$$, 'inline'),
  ('d683810e-f1b7-487f-aa08-c03b8c232b5f', '797dc471-175d-4a84-9137-7ef522c19414', $$ook de controlegroep werd geïnjecteerd$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context6.png$$,
   $$Om te dienen als controlegroep werd ook groep 3 geïnjecteerd.$$, 'inline'),
  ('e8667d85-580a-4c6a-ac4b-415e3daa2a74', '797dc471-175d-4a84-9137-7ef522c19414', $$afbeelding 3 (huidtemperatuur controlevleermuis) en afbeelding 4 (aantal keren wakker per periode)$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context7.png$$,
   $$Na de behandeling gingen alle vleermuizen onder gecontroleerde omstandigheden in winterslaap. Tijdens de winterslaap werd bijgehouden hoe vaak de dieren actief werden. Met sensoren op de huid werd de temperatuur van de vleermuizen gemeten en door video-observatie werd geteld hoe vaak de vleermuizen wakker werden. Voor de analyse verdeelden de onderzoekers de winterslaap in drie periodes van 26 dagen. In afbeelding 3 is de gemeten huidtemperatuur van een van de vleermuizen uit de controlegroep weergegeven. In afbeelding 4 staat hoe vaak er dieren per periode wakker werden.
afbeelding 3: huidtemperatuur (°C) van een controlevleermuis gedurende 80 dagen (periode 1, 2 en 3), met enkele korte pieken tot ongeveer 30 °C
afbeelding 4: staafdiagram van het totaal aantal keren wakker worden per groep (NAPd, EUPd, controle) in periode 1, 2 en 3; EUPd het vaakst, controle het minst$$, 'inline'),
  ('bcdaf79c-a7f7-4d18-b602-765bce9fe6d6', '797dc471-175d-4a84-9137-7ef522c19414', $$afbeelding 5: aantal overlevende vleermuizen per groep$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context8.png$$,
   $$In afbeelding 5 is weergegeven hoeveel dieren er tijdens het experiment overleefden.
afbeelding 5: aantal overlevende individuen (0-20) tegen de tijd (dagen, 0-120) voor de controlegroep, NAPd en EUPd; in de controlegroep overleven alle 18 dieren, in de EUPd-groep en de NAPd-groep sterven alle dieren vóór dag 120 (EUPd het eerst)$$, 'inline'),
  ('8059e744-a621-4eac-abad-1b333e84e20e', '797dc471-175d-4a84-9137-7ef522c19414', $$beoordelen of P. destructans verantwoordelijk is voor de massale sterfte$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context9.png$$,
   $$In combinatie met de veldwaarnemingen maakt dit onderzoek het mogelijk om te beoordelen of de schimmel P. destructans verantwoordelijk kan zijn voor de massale vleermuissterfte in Noord-Amerika.$$, 'inline'),
  ('d16a1d38-5400-4454-b063-daf64b697ce0', '797dc471-175d-4a84-9137-7ef522c19414', $$door infectie wel aspecifieke maar geen specifieke afweer$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context10.png$$,
   $$Door de lage lichaamstemperatuur is het immuunsysteem van de vleermuizen tijdens de winterslaap minder actief. Onderzoekers hebben aangetoond dat door de infectie met de schimmel het immuunsysteem wordt geactiveerd. Het bleek dat er dan wel sprake was van aspecifieke afweer, maar niet van specifieke afweer.$$, 'inline'),
  ('88cf59fe-8019-4caf-bbeb-e64205b80d1c', '797dc471-175d-4a84-9137-7ef522c19414', $$drie processen bij afweerreacties$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context11.png$$,
   $$Drie processen bij afweerreacties zijn:
1 deling van B-cellen
2 fagocytose door macrofagen
3 productie van antistoffen$$, 'inline'),
  ('96d78627-531f-4c40-b1e2-3a86fae3cc5d', '797dc471-175d-4a84-9137-7ef522c19414', $$warmere zones in grotten zodat vleermuizen immuniteit kunnen opbouwen$$,
   $$biologie-havo-2021-i-vleermuizen-bedreigd-context12.png$$,
   $$Om het uitsterven van vleermuissoorten te voorkomen, zoeken onderzoekers en natuurbeschermers naar een oplossing. Een optie is het tijdelijk inrichten van warmere zones in de grotten waar de vleermuizen overwinteren. Hierdoor zouden besmette vleermuizen immuniteit kunnen opbouwen tegen de schimmel en zou de sterfte kunnen worden voorkómen.$$, 'inline');

